const LOOKUP_SELECTOR='#heroTitle,#heroStrap,#heroIntro,#warmTask,#stationTitle,#stationSubtitle,#mainQuestion,#questions .question span:not(.qnum),#supportList li,#challengeReveal,#stretchReveal,#vocabGrid .vocab-item b,#vocabGrid .vocab-item span,#toolkitGrid .vocab-item span,#goalText';
